/* Level overlay code after gameplay/state; generated by `decomp overlays stubs`, stubs replaced by C as functions are matched. */
#include "types.h"
#include "asm.h"

/* Ported from rac1-decomp (src/overlays/shared/pause_0029C2A0.c: func_L01_0029C2A0), where it is exact; names translated to the US level program. */

typedef struct {
    int key;
    int pad4;
    unsigned short a;
    short flag;
    short c;
    short d;
} Entry;

typedef struct {
    int n;
    Entry e[1];
} Table;

extern void copy_memory_aligned(int, void *, int) __asm__("FUN_001f9838");

void FUN_L01_0029b0a0(char *source, int byte_count, char *p, int mode, Table *t) {
    short v20 = *(short *)(p + 0xB2);
    short v19 = *(short *)(p + 0xA6);
    short key;
    int i;
    Entry *e;
    Entry *ne;
    if (mode == 1) {
        key = source - p;
    } else {
        key = (int)source - *(unsigned short *)(p + 0x78);
    }
    for (i = 0; i < t->n; i++) {
        e = &t->e[i];
        if (e->key == key && e->a == byte_count && v20 == e->c && v19 == e->d) {
            mode = e->flag;
            if (mode) {
                copy_memory_aligned((int)&e->pad4, source, byte_count);
                return;
            }
        }
    }
    ne = &t->e[t->n];
    t->n = t->n + 1;
    ne->key = key;
    copy_memory_aligned((int)&ne->pad4, source, byte_count);
    ne->a = byte_count;
    ne->flag = mode;
    ne->c = v20;
    ne->d = v19;
}
